import random, importlib.util, sys

spec = importlib.util.spec_from_file_location("uhi_orig", "/tmp/uhi_orig.py")
orig = importlib.util.module_from_spec(spec); spec.loader.exec_module(orig)
sys.path.insert(0, ".")
import urban_micro.uhi as new

random.seed(42)
for trial in range(300):
    ncells = random.randint(0, 8)
    cells = [f"c{i}" for i in range(ncells)]
    labels = {c: random.choice(["u", "r", "x"]) for c in cells}
    details = []
    minutes = random.choice([60, 30, 120, 1440])
    for c in cells:
        for k in range(random.randint(0, 4)):
            t = random.randint(0, 5) * 900
            d = round(random.uniform(-5, 5), random.randint(0, 3))
            if random.random() < 0.3:
                d = int(d)
            details.append((t, c, 0.0, d, d, 0.0, 0.0, 0.0))
    neighbors = []
    for i in range(ncells):
        for j in range(i + 1, ncells):
            if random.random() < 0.4:
                e = (cells[i], cells[j]) if random.random() < 0.5 else (cells[j], cells[i])
                neighbors.append(e)
    lags = random.sample([1, 2, 3, 4], random.randint(0, 3))
    alpha = random.choice([0.05, 0.1, 1, 0.5])
    kwargs = dict(minutes=minutes, alpha=alpha)
    try:
        o = orig.effect_matrix_lags_group_fdr_report(details, neighbors, lags, labels, **kwargs)
    except Exception as e:
        o = (type(e).__name__, str(e))
    try:
        n = new.effect_matrix_lags_group_fdr_report(details, neighbors, lags, labels, **kwargs)
    except Exception as e:
        n = (type(e).__name__, str(e))
    assert o == n, (trial, o, n)
    # also compare the ungrouped lags fdr (untouched, but uses shared helpers)
    try:
        o2 = orig.effect_matrix_lags_fdr_report(details, neighbors, lags, **kwargs)
    except Exception as e:
        o2 = (type(e).__name__, str(e))
    try:
        n2 = new.effect_matrix_lags_fdr_report(details, neighbors, lags, **kwargs)
    except Exception as e:
        n2 = (type(e).__name__, str(e))
    assert o2 == n2, (trial, o2, n2)
print("300 randomized trials: old and refactored outputs byte-identical")
